// Warmup schedule:
// Phase 1 (week 1):   5 emails/day
// Phase 2 (week 2):  15 emails/day
// Phase 3 (week 3):  30 emails/day
// Phase 4 (week 4+): 50 emails/day
// Graduated:         50+ emails/day (monitoring only)

const WARMUP_SCHEDULE = {
  'phase_1': { daily_limit: 5,  next_phase: 'phase_2', min_days: 7,  description: 'Week 1: Slow start' },
  'phase_2': { daily_limit: 15, next_phase: 'phase_3', min_days: 7,  description: 'Week 2: Ramping up' },
  'phase_3': { daily_limit: 30, next_phase: 'phase_4', min_days: 7,  description: 'Week 3: Moderate volume' },
  'phase_4': { daily_limit: 50, next_phase: 'graduated', min_days: 7, description: 'Week 4: Target volume' },
  'graduated': { daily_limit: 50, next_phase: null, min_days: null, description: 'Warmup complete' },
  'paused':   { daily_limit: 0,  next_phase: null, min_days: null, description: 'Paused - reputation issue' },
  'test':     { daily_limit: 10, next_phase: 'phase_1', min_days: 1, description: 'Test mode' },
};

const domains = $input.all().map(i => i.json);
const results = [];

for (const domain of domains) {
  const currentPhase = domain.warmup_phase || 'phase_1';
  const schedule = WARMUP_SCHEDULE[currentPhase];

  if (!schedule) {
    results.push({
      domain: domain.domain,
      domain_id: domain.id,
      action: 'skip',
      reason: `Unknown warmup phase: ${currentPhase}`,
      current_phase: currentPhase,
    });
    continue;
  }

  // Check reputation health
  const reputation = domain.reputation_score || 100;
  if (reputation < 50 && currentPhase !== 'paused') {
    results.push({
      domain: domain.domain,
      domain_id: domain.id,
      action: 'pause',
      reason: `Reputation ${reputation} below threshold (50). Auto-pausing.`,
      current_phase: currentPhase,
      new_phase: 'paused',
      new_daily_limit: 0,
      alert: true,
    });
    continue;
  }

  // Check if ready to advance
  const phaseStartedAt = domain.warmup_phase_started_at || domain.created_at;
  const daysSincePhaseStart = Math.floor(
    (Date.now() - new Date(phaseStartedAt).getTime()) / (1000 * 60 * 60 * 24)
  );

  if (schedule.next_phase && schedule.min_days && daysSincePhaseStart >= schedule.min_days) {
    // Check bounce rate in current phase isn't too high
    // If reputation is still good, advance
    if (reputation >= 70) {
      const nextSchedule = WARMUP_SCHEDULE[schedule.next_phase];
      results.push({
        domain: domain.domain,
        domain_id: domain.id,
        action: 'advance',
        reason: `${daysSincePhaseStart} days in ${currentPhase}, reputation ${reputation} OK. Advancing.`,
        current_phase: currentPhase,
        new_phase: schedule.next_phase,
        new_daily_limit: nextSchedule.daily_limit,
        alert: false,
      });
    } else {
      results.push({
        domain: domain.domain,
        domain_id: domain.id,
        action: 'hold',
        reason: `${daysSincePhaseStart} days in ${currentPhase}, but reputation ${reputation} < 70. Holding.`,
        current_phase: currentPhase,
        alert: true,
      });
    }
  } else {
    // Not ready to advance yet
    const daysRemaining = schedule.min_days ? schedule.min_days - daysSincePhaseStart : 0;
    results.push({
      domain: domain.domain,
      domain_id: domain.id,
      action: 'no_change',
      reason: schedule.next_phase 
        ? `${daysSincePhaseStart}/${schedule.min_days} days in ${currentPhase}. ${daysRemaining} days remaining.`
        : `${currentPhase}: ${schedule.description}`,
      current_phase: currentPhase,
      days_in_phase: daysSincePhaseStart,
      days_remaining: daysRemaining > 0 ? daysRemaining : 0,
    });
  }
}

console.log(`Evaluated ${domains.length} domains: ${results.filter(r => r.action === 'advance').length} to advance, ${results.filter(r => r.action === 'pause').length} to pause`);

return results.map(r => ({ json: r }));

// Build summary for notification
const allResults = $('Evaluate Warmup Status').all().map(i => i.json);

const summary = {
  total_domains: allResults.length,
  advanced: allResults.filter(r => r.action === 'advance').map(r => `${r.domain}: ${r.current_phase} -> ${r.new_phase} (${r.new_daily_limit}/day)`),
  paused: allResults.filter(r => r.action === 'pause').map(r => `${r.domain}: ${r.reason}`),
  holding: allResults.filter(r => r.action === 'hold').map(r => `${r.domain}: ${r.reason}`),
  no_change: allResults.filter(r => r.action === 'no_change').map(r => `${r.domain}: ${r.reason}`),
  has_alerts: allResults.some(r => r.alert),
};

const lines = ['=== WARMUP MANAGER REPORT ===', ''];

if (summary.advanced.length > 0) {
  lines.push('ADVANCED:');
  summary.advanced.forEach(l => lines.push(`  + ${l}`));
  lines.push('');
}

if (summary.paused.length > 0) {
  lines.push('PAUSED (action needed):');
  summary.paused.forEach(l => lines.push(`  ! ${l}`));
  lines.push('');
}

if (summary.holding.length > 0) {
  lines.push('HOLDING (reputation recovery needed):');
  summary.holding.forEach(l => lines.push(`  ? ${l}`));
  lines.push('');
}

if (summary.no_change.length > 0) {
  lines.push('STATUS QUO:');
  summary.no_change.forEach(l => lines.push(`  - ${l}`));
}

return [{ json: { ...summary, formatted_text: lines.join('\n') } }];
